    },
    {
      "card_ids": ["C08"],
      "claim": "Pritelivir showed 75% oral bioavailability after a single 100 mg dose, supporting high bioavailability.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All usable transferred evidence molecules show absolute oral bioavailability at or above 20%, with most values well above the threshold; therefore the prediction is high.",
  "evidence_gaps": [
    "Molecule 10 groups records for alfentanil and alprazolam under one name; those inconsistent cards were discounted due to provenance conflict.",
    "Molecule 6 reports only qualitative 'excellent' bioavailability without a numeric value, providing weaker quantitative support.",
    "Molecule 9 is a predicted human bioavailability value (23%) rather than a direct measured value, though it still supports the high category."
  ],
